{"content":"// Frontend controller for the RAZOR Service Manager.
// Polls /api/services and wires the start/stop buttons.

const API = "/api/services";

async function loadServices() {
  const res = await fetch(API);
  const services = await res.json();
  renderTable(Array.isArray(services) ? services : [services]);
}

function renderTable(services) {
  const tbody = document.querySelector("#services tbody");
  tbody.innerHTML = "";
  for (const svc of services) {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${svc.Display || svc.Name}</td>
      <td class="status ${svc.Status}">${svc.Status}</td>
      <td>
        <button onclick="controlService('${svc.Name}','start')">Start</button>
        <button onclick="controlService('${svc.Name}','stop')">Stop</button>
      </td>`;
    tbody.appendChild(row);
  }
}

async function controlService(name, action) {
  await fetch(`${API}/${name}/${action}`, { method: "POST" });
  await loadServices();
}

setInterval(loadServices, 5000);
loadServices();
